def count_trees(n, k):
    if n < k:
        return 0
    if n == 1:
        return 0 if k == 1 else 1
    if n == 2:
        return k if k == 1 else 1
    if n == 3:
        return 3 if k == 1 else k if k == 2 else 2
    if n == 4:
        return 3 * (k + 3)
    dp = [0] * (n + 1)
    dp[1] = 2 if k == 1 else 1
    dp[2] = k * 4 + (k - 1) * 2 + (1 - k) if k == 1 else 4 * (k + 1)
    dp[3] = 3 * (k * 3 + (k - 1) + (k - 1) * 3 + (3 - k) * 2) + k * (k - 3) + (1 - k) * k - 1
    dp[4] = 3 * (k * 13 + (k - 1) + (k - 2) * 3 + (k - 2) * (k - 2)) + k * (37 - 22) + (1 - k) * (13 + 2 + k - 4 - 1 + k)
    dp[5] = 3 * (k * 35 + (k - 1) + (k - 2) * 14 + (k - 3) * (36 - 11) + (k - 3) * (36 - 8) + (1 - k) * 4)
    for i in range(6, n + 1):
        next_dp = k * (dp[i - 1] + 3 * dp[i]) + (1 - k) * (dp[i] + 2 * dp[i - 1] + dp[i - 2]) + dp[i - 1]
        dp[i] = next_dp % 1000000007
    return dp[n]

