import sys
from itertools import combinations

def find_parent(parent, x):
    if parent[x] != x:
        parent[x] = find_parent(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    px = find_parent(parent, x)
    py = find_parent(parent, y)
    if px == py:
        return False
    if rank[px] < rank[py]:
        parent[px] = py
    elif rank[px] > rank[py]:
        parent[py] = px
    else:
        parent[py] = px
        rank[px] += 1
    return True

def create_tree_with_distances(nodes, distances):
    parent = {i: i for i in range(1, nodes+1)}
    rank = {i: 0 for i in range(1, nodes+1)}
    nearest = {i: 0 for i in range(1, nodes+1)}
    for dist in distances:
        i = nearest[find_parent(parent, i)] + 1
        nearest[find_parent(parent, i)] = dist
        neighbors = list(nearest.keys())
        for j, g in enumerate(neighbors):
            if j != i:
                union(parent, rank, i, g)
    if find_parent(parent, 1) == find_parent(parent, 2):
        return None
    else:
        leaves = [i for i in parent if parent[i] == i]
        leaves_to_remove = set()
        for i, e in enumerate(distances):
            if i in leaves and 2 <= e <= nodes-1:
                leaves_to_remove.add(i)
                distance = e
        edges = set()
        for i in range(len(distances)):
            if i not in leaves_to_remove:
                edges.add((distances[i][0]-1, distances[i][1]-1))
        edges = sorted(list(edges), key=lambda x: distances[x[0]])
        edges.sort(key=lambda x: distances[x[0]+1])
        for u, v in edges:
            if not union(parent, rank, u+1, v+1):
                return None
        leaves_to_remove = [e-1 for e in leaves_to_remove]
        all_leaves = []
        for i in range(nodes):
            neighbor_check = {j: False for j in nearest.keys()}
            cur = i
            while cur != 1:
                if not neighbor_check[cur]:
                    neighbor_check[cur] = True
                    if cur == find_parent(parent, cur):
                        break
                cur = find_parent(parent, cur)
            if cur == 1:
                leave = parent[cur]
                all_leaves.append(leave)
        return all_leaves

