from itertools import product

def count_distinct_arrays(n, k, m, conditions):
    if m == 0:
        return 1

    MOD = 998244353
    prefix = [0] * (n + 1)
    for l, r, x in conditions:
        prefix[r] ^= x

    for i in range(1, n + 1):
        prefix[i] ^= prefix[i - 1]

    dp = [0] * (2 ** n)
    dp[0] = 1
    dp_s = [product(range(2 ** n), repeat=2) ** (i << 1) for i in range(m + 1)]

    def combine(a, b):
        result = 1
        for i in range(len(a)):
            result *= dp[i]
            result %= MOD
            for j in range(len(b[i])):
                if b[i][j] == 0:
                    result //= (dp_s[i][j] ** k)
                    result %= MOD
        return result

    for i in range(2 ** n):
        found = False
        for j in range(m + 1):
            b = dp[:]  # Use shallow copy
            part = dp_s[j]
            for key, val in part[i].items():
                result = 0
                for k in range(len(key)):
                    if val == 0:
                        break
                    result += combine(key[:k], key[k + 1:])
                if result != 0:
                    for k in range(len(key)):
                        dp_s[j][k][key[k]] -= result
            if result == 0:
                continue
            dp[i] += result
            dp[i] %= MOD
        if dp[i] == 0:
            found = True
            break

    return dp[0] % MOD

