from operator import mul

def min_function(A, x, k):
    bit = 1 << k
    target = x >> k
    for i in range(bit):
        if A & bit == target:
            return i

def max_function(A, x, k):
    bit = 1 << k
    if x <= 0:
        return 0
    else:
        return bit - min_function(A, x, k) - 1

def cnt_of_ways(A, k, begin, end):
    if k == 1:
        return end - begin + 1
    mid = (begin + end) // 2
    if begin >= end:
        return 1
    lCnt = cnt_of_ways(A, k - 1, begin, 2 ** (k - 1) - 1)
    rCnt = min_function(A, (2 ** (k - 1)) - 1, k)
    if rCnt < mid or mid < min_function(A, begin, k):
        return lCnt
    else:
        return begin + 2 ** (k - 1) - 1 - rCnt + lCnt

def count_ways(n, k, m, A):
    bit = 1 << k
    res = 0
    for i in range(n):
        if max_function(A, A[i] & bit - 1, k) > i:
            i += 1
        else:
            A = A[:i] + [bit - 1 - (i - max_function(A, A[i] & bit - 1, k))]
        if min_function(A, (2 ** k) - 1, k) >= i:
            i += 1
        else:
            A = A[:i] + [bit - 1 - (2 ** (k - 1) + 1)]
        if len(A) == m + 1:
            res += 1
    return res

