def sum_of_subsequences(sum_tuple: List[int]) -> int:
    """
    Calculate the sum of a list of tuples where each tuple represents a subsequence sum.
    """
    total_sum = sum(sum_tuple[0])
    for i in range(1, len(sum_tuple)):
        total_sum += sum(sum_tuple[i]) - sum((reduce(lambda x, y: x + y, s) for s in zip(*sum_tuple[i])))

    return total_sum

def character_to_kings(mdpre: int) -> List[int]:
    kongzi = []
    while True:
        sub_mask = 0
        for j in range(len(mdpre)):
            if mdpre[j] % 2 == 0:
                sub_mask += 2 ** j
        if sub_mask > 0:
            kongzi.append(sub_mask)
            tmp_bit = sub_mask
            i = 0
            for j in range(tmp_bit):
                if tmp_bit & i:
                    continue
                mdpre[j] -= 1
                if mdpre[j] % 2 == 0:
                    tmp_bit |= 1 << j
            mdpre = [i * 2 - 2 + 2 * mdpre[i] for i in range(len(mdpre))]
            return character_to_kings(mdpre)
        else:
            break
    return kongzi

def beautiful_submatrices(rows: int, cols: int, matrix: List[str]) -> int:
    matrix = [ord(c)-32 for row in matrix for c in row]
    result = 0
    for sublen in range(1, min(len(matrix), 2 * min(rows, cols)) + 1):
        for j in range(0, rows - sublen + 1):
            for k in range(0, cols - sublen + 1):
                kongzi = character_to_kings([1 if c == ord("0") else matrix[i + k] for i, c in enumerate(matrix[j:j + sublen])])
                result += sum_of_subsequences(kongzi)
    return result // 2   # Odd number of subsequence combinations, divide by 2

