def maxRectangleArea(ordinates: List[int]) -> int:
    stack = []
    max_area = 0
    for i, y in enumerate(ordinates):
        while stack and ordis[i] < ordest[stack[-1]]:
            h = ordy[stack.pop()]
            w = i - stack[-1] - 1
            max_area = max(max_area, h * w)
        stack.append(i)
    while stack:
        h = ordy[stack.pop()]
        w = len(ordinates) - stack[-1] - 1
        max_area = max(max_area, h * w)
    return max_area

def area_of_minimum_rectangles(test_cases: List[List[int]]) -> List[int]:
    output = []
    for N, K in test_cases:
        if N < 2 * K:
            output.append(-1)
        else:
            ordy, ordx = [0] * 2 * N, [0] * N
            for i in range(N):
                ordy[i] = ordx[i] = i
                ordy[K + i] = ordx[K + i] = K + N - i - 1
            rect_area = maxRectangleArea(ordy)
            if rect_area > 0:
                output.append(rect_area)
            else:
                output.append(-1)
    return output
