def process_queries(n, nums, q, queries):
    # Store elements that need to be updated
    elements_to_update = [i for l, r, x, y in queries if x != y]

    # Flood fill the array from the beginning, 0-based
    for i in range(q):
        l, r, x, y = queries[i]
        if elements_to_update:
            nums[r] = y if y != nums[r] else None
            nums[l-1 if l > 0 else -1] = y if y != nums[l-1 if l > 0 else -1] else None
            for l_loc in range(l-2, -1, -1) if l > 1 else [1, None]:
                if nums[l_loc] is None and l_loc in elements_to_update:
                    nums[l_loc] = y
            for r_loc in range(r+1, n) if r < 9999 else [9999, None]:
                if nums[r_loc] is None and r_loc in elements_to_update:
                    nums[r_loc] = y
        else:
            nums[r] = y if y != nums[r] else None

    # Convert the modified flat indices and restore original positions
    for j in range(q):
        i, r, x, y = queries[j]
        nums[r] = y if y == nums[r] else nums[r]
    return nums

