import sys

mod = 1000000007

def count_trees(n, k, dp):
    if dp[n][k] == -1:
        if n == 1:
            if k == 0:
                dp[n][k] = 1
            else:
                dp[n][k] = 0
        else:
            total_trees = 0
            for i in range(k + 1):
                to_add = (count_trees(n - 1, i, dp) * binomial_coefficient(n - 1, i)) % mod
                if i == k:
                    total_trees += (to_add - 1 + mod) % mod
                else:
                    total_trees += to_add
                total_trees %= mod
            dp[n][k] = total_trees
    return dp[n][k]

def binomial_coefficient(n, k):
    if k > n - k:
        k = n - k
    result = 1
    for i in range(k):
        result *= (n - i)
        result //= (i + 1)
    return result

