MOD = 1000000007

def count_trees(n, k, visited=None, match=None):
    if visited is None:
        visited = [False] * (n + 1)
    if match is None:
        match = [-1] * (n + 1)
    if visited[1] or n <= 1 or k <= 1:
        return 1 if n and match[1] == -1 else 0

    result = 0
    for i in range(1, n + 1):
        if not visited[i] and match[i] == -1:
            visited[i] = True
            result = (result + count_trees(n - 1, k, visited, match)) % MOD
            match[i] = match[1]

    return result

