mod = 1000000007

def mod_add(x, y):
    return (x + y) % mod

def mod_sub(x, y):
    return (x - y) % mod

def mod_mul(x, y):
    return (x * y) % mod

def mod_pow(x, e):
    if e == 0: return 1
    if e == 1: return x % mod
    if e % 2 == 0:
        half = mod_pow(x, e // 2)
        return mod_mul(half, half)
    else:
        half = mod_pow(x, e // 2)
        return mod_mul(mod_mul(half, half), x)

def mod_inv(x):
    return mod_pow(x, mod - 2)

def init_kuhn(n, m):
    answer = mod_mul(mod_mul(2, mod_add(m, 1)), mod_add(n + 3, 1))
    answer = mod_sub(mod_pow(answer, 2), 2)
    answer = mod_sub(mod_add(answer, 2), n <= 2)
    return mod_add(answer, 2)

