import sys

def minimize_waiting_time(n, m, p, heights, times):
    dp = [float('inf')] * (n + 1)
    dp[0] = 0  # No waiting at the starting point
    heap = [(0, 0)]  # (waiting time, position)

    for _ in range(p):
        waiting_time, current_position = heapq.heappop(heap)
        for next_position, time_to_next in enumerate(heights[current_position:], start=current_position + 1):
            if dp[next_position] > waiting_time + time_to_next:
                dp[next_position] = waiting_time + time_to_next
                heapq.heappush(heap, (dp[next_position], next_position))

    return sum(dp)

