from math import gcd

def extended_gcd(a, b):
    if a == 0:
        return (b, 0, 1)
    gcd, x1, y1 = extended_gcd(b % a, a)
    x = y1 - (b // a) * x1
    y = x1
    return (gcd, x, y)

def mod_inverse(a, m):
    gcd, x, y = extended_gcd(a, m)
    if gcd != 1:
        raise ValueError('Multiplicative inverse does not exist')
    else:
        return x % m

def optimize_schedule(n, k):
    periods = {}
    for end in range(1, n + 1):
        start = end - k
        while start >= 0:
            periods[start] = end
            start -= 1
    total_days = 0
    for i in days:
        total_days += periods[i] - i
    mod_inverse_days = mod_inverse(k, n + k)
    return total_days * mod_inverse_days % (10**9 + 7)

